/// Opens the binary, as [`Embedded::open`] says.
async fn open(options: Options) -> Result<Embedded, Failure> {
    let data = options.data_dir;
    std::fs::create_dir_all(data.join(DATABASES_DIR))
        .map_err(|err| format!("the data directory {}: {err}", data.display()))?;

    // Before any request is served, each file goes to the model the
    // carried plans end at (D116).
    migrate_file(&data, "fixture-timers-db", FIXTURE_TIMERS_DB_FILE)?;

    // What the environment binds, where the process's environment says
    // nothing, and each database field's file.
    for (name, value) in BOUND {
        if std::env::var_os(name).is_none() {
            std::env::set_var(name, value);
        }
    }
    bind_file(
        &data,
        "FIXTURE_TIMERS_DB_DATABASE_URL",
        FIXTURE_TIMERS_DB_FILE,
    );

    // Each API's configuration, from the environment.
    let fixture_timers_api_config = configure(
        "fixture-timers-api",
        fixture_timers_api_api::config::load_env_config(),
    )?;

    // One open file per database, shared by every API on it: a write
    // waits its turn on the file's one writing connection.
    let fixture_timers_db_pool = open_file(
        "fixture-timers-db",
        "FIXTURE_TIMERS_DB_DATABASE",
        &fixture_timers_api_config.fixture_timers_db_database,
    )?;

    let apis = Arc::new(Apis::default());

    // fixture-timers-api: its implementation, built from its Deps.
    let fixture_timers_api_deps = fixture_timers_api_api::Deps {
        config: fixture_timers_api_config.clone(),
        db: fixture_timers_db_pool.clone(),
        span: logging::api_span("fixture-timers-api"),
    };
    let fixture_timers_api_handlers = fixture_timers_api_impl::create(fixture_timers_api_deps)
        .await
        .map_err(|err| format!("implementation of fixture-timers-api: {err}"))?;
    let fixture_timers_api_implementations = fixture_timers_api_api::Implementations::new(
        fixture_timers_api_handlers,
        fixture_timers_db_pool.clone(),
    );
    let fixture_timers_api_router =
        fixture_timers_api_api::Api::new(fixture_timers_api_implementations);
    hold(&apis.fixture_timers_api, Some(fixture_timers_api_router));

    // Worker fixture-timers-api-ticket-timers: TicketTimers of
    // fixture-timers-api, whose queues are claimed on fixture-timers-db's file.
    let ticket_timers_worker_queues = fixture_timers_api_api::behaviors::ticket_timers_worker()?;
    let ticket_timers_worker = Worker::new(
        "fixture-timers-api-ticket-timers",
        ticket_timers_worker_queues,
        &fixture_timers_db_pool,
        2,
        5,
    );

    tracing::info!(
        stack = STACK,
        environment = ENVIRONMENT,
        data = %data.display(),
        "opened"
    );
    Ok(Embedded {
        apis,
        workers: vec![ticket_timers_worker],
    })
}

/// Takes the file of `service` under `data` to the model the plans the
/// binary carries for it end at, and creates it when it is missing.
fn migrate_file(data: &Path, service: &str, file: &str) -> Result<(), Failure> {
    let carried = carried::DATABASES
        .iter()
        .find(|database| database.service == service)
        .filter(|database| !database.plans.is_empty())
        .ok_or_else(|| {
            format!(
                "database {service}: this binary carries no plan of it, so it cannot make or \
                 migrate its file; build the binary with `superschematic stack build {ENVIRONMENT}`"
            )
        })?;
    let path = data.join(file);
    let mut log = |line: &str| tracing::info!(database = service, "{line}");
    let started = migrate::start(
        &path,
        carried.plans,
        migrate::StartOptions {
            adoption: carried.adoption.as_ref().map(|adoption| migrate::Adoption {
                model: adoption.model,
                check: adoption.check,
            }),
            wal: true,
            log: Some(&mut log),
        },
    )
    .map_err(|err| format!("database {service}, at {}: {err}", path.display()))?;
    tracing::info!(
        database = service,
        model = %started.model,
        plans = started.plans.len(),
        adopted = started.adopted,
        release = carried::RELEASE,
        "migrated"
    );
    Ok(())
}

/// Sets the database field's variable `name` to the file `file` under
/// `data`, as a stack's sql edge derives it.
fn bind_file(data: &Path, name: &str, file: &str) {
    std::env::set_var(name, format!("sqlite:{}", data.join(file).display()));
}

/// An API's configuration, or a failure naming the API and each variable
/// missing or invalid.
fn configure<T, E: std::fmt::Display>(api: &str, loaded: Result<T, E>) -> Result<T, Failure> {
    loaded.map_err(|err| format!("configuration of {api}: {err}").into())
}

/// Opens the SQLite file of the database field named `field` (the HTTP
/// runtime's `orm::sqlite`): one writing connection and a few reading
/// ones, in WAL mode. The file is there already: the start migrated it.
fn open_file(service: &str, field: &str, database: &Database) -> Result<Arc<SqliteFile>, Failure> {
    sqlite::connect(database)
        .map_err(|err| format!("database {service}, from {field}: {err}").into())
}

/// Whether `path` is `base` or a path under it.
fn under(path: &str, base: &str) -> bool {
    path.strip_prefix(base)
        .is_some_and(|rest| rest.is_empty() || rest.starts_with('/'))
}

/// `request` with `base` taken off its path, the query kept, as the API
/// under `base` reads it.
fn inner(request: Request<Bytes>, base: &str) -> Request<Bytes> {
    let (mut parts, body) = request.into_parts();
    let path = parts.uri.path().strip_prefix(base).unwrap_or("/");
    let path = if path.is_empty() { "/" } else { path };
    let target = match parts.uri.query() {
        Some(query) => format!("{path}?{query}"),
        None => path.to_owned(),
    };
    if let Ok(uri) = target.parse::<Uri>() {
        parts.uri = uri;
    }
    Request::from_parts(parts, body)
}

/// A whole response of `status` holding `body`.
fn answer(status: StatusCode, content_type: &'static str, body: &'static [u8]) -> Response<Bytes> {
    let mut response = Response::new(Bytes::from_static(body));
    *response.status_mut() = status;
    response
        .headers_mut()
        .insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    response
}

/// The answer to a request for an API the binary has let go of.
fn closed(api: &str) -> Response<Bytes> {
    tracing::warn!(api, "a request after the binary closed");
    answer(
        StatusCode::SERVICE_UNAVAILABLE,
        "text/plain; charset=utf-8",
        b"the binary is closed\n",
    )
}

/// Answers a request that is no API's from the site's files (D55): the
/// file its path names, `index.html` for a directory, the site's config
/// at [`SITE_CONFIG_PATH`], the fallback for a path that names no file,
/// and 404 without one. A file's ETag is its digest, so a browser that
/// holds it is answered 304.
fn site(request: &Request<Bytes>) -> Response<Bytes> {
    let head = request.method() == Method::HEAD;
    if request.method() != Method::GET && !head {
        return answer(
            StatusCode::METHOD_NOT_ALLOWED,
            "text/plain; charset=utf-8",
            b"the site answers GET and HEAD\n",
        );
    }
    let path = request.uri().path();
    if path == SITE_CONFIG_PATH && !SITE_APIS.is_empty() {
        return site_config(request, head);
    }
    let name = path.trim_matches('/');
    let index = format!("{name}/index.html");
    let found = site_file(if name.is_empty() { "index.html" } else { name })
        .or_else(|| site_file(&index))
        .or_else(|| SITE_FALLBACK.and_then(site_file));
    let Some(file) = found else {
        return answer(
            StatusCode::NOT_FOUND,
            "text/plain; charset=utf-8",
            b"not found\n",
        );
    };
    let unchanged = request
        .headers()
        .get(IF_NONE_MATCH)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|held| held.split(',').any(|tag| tag.trim() == file.etag));
    let status = if unchanged {
        StatusCode::NOT_MODIFIED
    } else {
        StatusCode::OK
    };
    let body = if head || unchanged {
        &[][..]
    } else {
        file.body
    };
    let mut response = answer(status, file.content_type, body);
    let headers = response.headers_mut();
    headers.insert(ETAG, HeaderValue::from_static(file.etag));
    // A browser asks again each time, and is answered 304 while it holds
    // the file the binary carries.
    headers.insert(CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    response
}

/// The site's file at `path`, when the binary carries one.
fn site_file(path: &str) -> Option<&'static SiteFile> {
    carried::SITE.iter().find(|file| file.path == path)
}

/// The site's config: each API its page calls, at the API's path on the
/// origin the request named, so the page reaches it wherever the binary
/// listens.
fn site_config(request: &Request<Bytes>, head: bool) -> Response<Bytes> {
    let named = request
        .headers()
        .get(HOST)
        .and_then(|value| value.to_str().ok());
    let asked = request.uri().authority().map(|asked| asked.as_str());
    let host = named.or(asked).unwrap_or("127.0.0.1");
    let apis: serde_json::Map<String, serde_json::Value> = SITE_APIS
        .iter()
        .map(|(api, path)| {
            let url = format!("http://{host}{path}");
            ((*api).to_owned(), serde_json::json!({ "url": url }))
        })
        .collect();
    let mut body = serde_json::json!({ "apis": apis }).to_string();
    body.push('\n');
    if head {
        body.clear();
    }
    let mut response = Response::new(Bytes::from(body));
    let headers = response.headers_mut();
    headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
    headers.insert(CACHE_CONTROL, HeaderValue::from_static("no-store"));
    response
}
